# DK SSB.  Sønderborg - Skovby
#
let ss = path("d3.dk.ssb");

with detail = 3, railway = :first :g1000 :pax :removed {
    with link = "line.dk.SSB" {
        track(ss[:vol.yv, :vol - 0.49sw]);
    }

    with link = "point.dk.Vollerup-ABA", railway = :station {
        track(ss[:vol - 0.5sw, :vol.yn]);
        marker(:right :de.bf :casing, ss[:vol] >> 0.5lt);
    }

    with link = "line.dk.SSB" {
        track(ss[:vol.yn - 0.1dl, :vol.yn + 1.21km]);
        line_label(:left:s, ss[:vol.yn + 1.2km] << 0.5lt, "SSB");
        track(:station, ss[:vol.yn + 1.19km, :vol.yo]);
    }

    with link = "point.dk.Bjørnemosegaard", railway = :station {
        track(ss[:maj.yo, :bjo + 0.5sw]);
        marker(:right :de.hp :casing, ss[:bjo] >> 0.5lt);
        slabel(:ne, ss[:bjo] >> 0.5lt >> 1sh + (2dt, 0dt),
            vbox(:right:top, "Bjørne-", "mosegaard ")
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:bjo + 0.49sw, :tan - 0.49sw]);
    }

    with link = "point.dk.Tandslet", railway = :station {
        track(ss[:tan - 0.5sw, :tan + 0.5sw]);
        marker(:right :de.bf :casing, ss[:tan] >> 0.5lt);
        slabel(:top, ss[:tan] << 0.5lt << 0.6dt, "Tandslet");
    }

    with link = "line.dk.SSB" {
        track(ss[:lmo.ys, :lys - 0.49sw]);
    }

    with link = "point.dk.Lysabild", railway = :station {
        track(ss[:lys - 0.5sw, :lys + 0.5sw]);
        marker(:left :de.bf, ss[:lys] << 0.5lt);
        slabel(:right, ss[:lys] << 0.5lt << 1sh + (1.4dt, 1.6dt),
            "Lysabild"
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:lys + 0.49sw, :lys + 0.71km]);
        line_label(:right:s, ss[:lys + 0.7km] >> 0.5lt, (-0.5dt, 0dt), "SSB");
        track(ss[:lys + 0.69km, :fje - 0.49sw]);
    }

    with link = "point.dk.Fjelby", railway = :station {
        track(ss[:fje - 0.5sw, :fje + 0.5sw]);
        marker(:right :de.bf, ss[:fje] >> 0.5lt);
        slabel(:left, ss[:fje] >> 0.5lt >> 1sh + (-1.2dt, 1.1dt),
            "Fjelby"
        );
    }

    with link = "line.dk.SSB" {
        track(ss[:fje + 0.49sw, :sko - 0.49sw]);
    }

    with link = "point.dk.Skovby-Als", railway = :station {
        track(ss[:sko - 0.5sw, :sko + 0.5sw]);
        marker(:left :de.bf, ss[:sko] << 0.5lt);
        slabel(:right, ss[:sko] << 0.5lt << 1sh + (1.2dt, 1dt),
            span(:bold, "Skovby")
        );
    }
}

